 function quiz(){const b=state.battle,c=CREATURE_BY_ID[b.id],pool=FISH.filter(f=>f.grade===c.grade);return b.round===0?FISH_BY_ID[c.wordId]:pool[(c.number+b.round*7)%pool.length]}
 function renderBattle(){const b=state.battle,c=CREATURE_BY_ID[b.id],q=quiz(),listen=b.round%3===1;b.locked=false;refresh();body.innerHTML=`<div class="rpg-eyebrow">WORD ENCOUNTER · ${c.rarity}</div><h2>${c.name} があらわれた！</h2><div class="rpg-battle-meters"><div><small>きずな · あと ${3-b.hits} 正解</small><b>${'◆'.repeat(b.hits)}${'◇'.repeat(3-b.hits)}</b></div><div><small>集中力</small><b>${'♥'.repeat(3-b.misses)}${'♡'.repeat(b.misses)}</b></div></div><p>3問正解すると仲間になります。時間制限はありません。</p><div class="rpg-question"><span>英検${q.grade}級の目安 · ${listen?'聞いて答えよう':'意味を答えよう'}</span><strong id="rpg-question-word">${listen?'Listening…':q.word}</strong><button id="rpg-question-audio">▷ 単語を聞く</button>${listen?'<button id="rpg-word-hint">文字のヒントを見る</button>':''}</div><div class="rpg-answers">${choicesFor(q).map(o=>`<button data-rpg-answer="${o.id}">${o.meaning}</button>`).join('')}</div><p id="rpg-feedback" class="rpg-feedback" role="status"></p><div id="rpg-next-step"></div>`;$('#rpg-question-audio').onclick=()=>speak(q.word);if(listen)$('#rpg-word-hint').onclick=()=>$('#rpg-question-word').textContent=q.word;document.querySelectorAll('[data-rpg-answer]').forEach(button=>button.onclick=()=>answer(button.dataset.rpgAnswer));}
 function answer(id){if(adventure)return adventure.answer(id);const b=state.battle;if(state.mode!=='battle'||!b||b.locked)return;b.locked=true;const q=quiz(),correct=id===q.id;document.querySelectorAll('[data-rpg-answer]').forEach(x=>x.disabled=true);if(correct){b.hits++;learn(q.word,q.meaning);roundPulse=1;$('#rpg-feedback').textContent='✓ '+q.word+' = '+q.meaning+' · きずなが深まった！'}else{b.misses++;$('#rpg-feedback').textContent=q.word+' は「'+q.meaning+'」。次のことばでもう一度！'}if(b.hits>=3){win();return}if(b.misses>=3){lose();return}$('#rpg-next-step').innerHTML='<button class="primary" id="rpg-next-question">次のことばへ →</button>';$('#rpg-next-question').onclick=()=>{b.round++;renderBattle()}}
 function win(){const c=CREATURE_BY_ID[state.battle.id],result=store.capture(c.id);state.busy=false;state.mode='result';page='result';syncBuddy();refresh();showCreature(c.id);body.innerHTML=`<div class="rpg-eyebrow">${result.isNew?'NEW COMPANION':'BOND GROWS'}</div><h2>${c.name} と心がつながった！</h2><p>${c.lore}</p><div class="rpg-capture-result"><strong>${result.isNew?'+40 XP · 新しい仲間！':'+10 XP · きずなレベルアップ'}</strong><span>仲間 ${store.state.caught.length} / 100</span></div>${result.unlocked.length?`<div class="rpg-unlock"><small>NEW ROUTES UNLOCKED</small><h3>新しい航空路が開いた！</h3><p>${result.unlocked.map(id=>REGION_BY_ID[id].name).join(' ／ ')}</p></div>`:`<p>${REGION_BY_ID[c.region].name}：${store.count(c.region)} / 10 種類 · ${store.cleared(c.region)?'地域クリア済み':'あと '+(3-store.count(c.region))+' 種類で地域クリア'}</p>`}<div class="rpg-result-actions"><button class="primary" id="rpg-win-buddy">一緒に冒険する →</button><button id="rpg-win-map">ワールドマップ</button><button id="rpg-win-continue">探検をつづける</button></div>`;$('#rpg-win-buddy').onclick=()=>{store.selectBuddy(c.id);syncBuddy();modal.close();toast(c.name+' がついてきます！')};$('#rpg-win-map').onclick=()=>{selected=result.unlocked[0]||state.current;renderMap()};$('#rpg-win-continue').onclick=()=>modal.close()}
